import sys


def keyword_search(docs, query, k):
    """docs: {doc_id: text}. Words are compared in lower case after stripping .,?!;:()\"' from both ends. A document's score is the sum, over the DISTINCT query words, of how many times that word appears in it. Return up to k (doc_id, score) with score > 0, highest first, ties by doc_id in string order."""
    strip = ".,?!;:()\"'"
    terms = {w.lower().strip(strip) for w in query.split()} - {""}
    scored = []
    for doc_id, text in docs.items():
        counts = {}
        for word in text.split():
            word = word.lower().strip(strip)
            counts[word] = counts.get(word, 0) + 1
        score = sum(counts.get(term, 0) for term in terms)
        if score > 0:
            scored.append((doc_id, score))
    scored.sort(key=lambda s: (-s[1], s[0]))
    return scored[:k]


def main():
    data = sys.stdin.read().split("\n")
    k = int(data[0])
    n = int(data[1])
    docs = {}
    for i in range(n):
        parts = data[2 + i].split()
        docs[parts[0]] = " ".join(parts[1:])
    query = data[2 + n]
    ranked = keyword_search(docs, query, k)
    if not ranked:
        print("NONE")
    for doc_id, score in ranked:
        print(doc_id, score)


main()

import json
import sys


def check_output(line):
    """line: one reply from the model. Return 'VALID', or the first problem found, checked in this order: 'BAD_JSON' (not a JSON object), 'BAD_INTENT' (intent missing or not one of refund, booking_status, handoff), 'BAD_BOOKING_ID' (booking_id missing, not an integer (true/false do not count) or not > 0)."""
    try:
        reply = json.loads(line)
    except ValueError:
        return "BAD_JSON"
    if not isinstance(reply, dict):
        return "BAD_JSON"
    if reply.get("intent") not in ("refund", "booking_status", "handoff"):
        return "BAD_INTENT"
    booking = reply.get("booking_id")
    if isinstance(booking, bool) or not isinstance(booking, int) or booking <= 0:
        return "BAD_BOOKING_ID"
    return "VALID"


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    for i in range(n):
        print(check_output(data[1 + i]))


main()

