import heapq
import sys


def plan(needs):
    """needs: {tool: [tools that must run before it]}; every listed tool is a key. Return an order to run every tool so each runs after all its prerequisites, always picking the alphabetically first tool that is ready; return None if the dependencies contain a cycle."""
    waiting = {tool: len(deps) for tool, deps in needs.items()}
    unlocks = {tool: [] for tool in needs}
    for tool, deps in needs.items():
        for dep in deps:
            unlocks[dep].append(tool)
    ready = [tool for tool, count in waiting.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        tool = heapq.heappop(ready)
        order.append(tool)
        for nxt in unlocks[tool]:
            waiting[nxt] -= 1
            if waiting[nxt] == 0:
                heapq.heappush(ready, nxt)
    return order if len(order) == len(needs) else None


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    needs = {}
    for i in range(n):
        tool, deps = data[1 + i].split()
        needs[tool] = [] if deps == "-" else deps.split(",")
    order = plan(needs)
    print(" ".join(order) if order is not None else "CYCLE")


main()
